update the field `status` in the markdown feature description file to `ready for implementation`.

Read all referenced files before you begin except `agents` files. it is possible that the file is not yet written. &#x20;
Ask any question if something is ambiguous or not yet clear.
Be brief, but never compress away the subject, timing, or causal chain. Define ambiguous technical phrases. use $caveman skill.

Do not stage or commit changes. You have no need for get at this time.

import type {
    AgentConversationEntry,
    AgentConversationEventEntry,
} from '../../../data/data_types'
import { eventIdentity } from './event_display'

const TOOL_CALL_EVENT_TYPES = new Set([
    'collabAgentToolCall',
    'commandExecution',
    'dynamicToolCall',
    'fileChange',
    'imageView',
    'mcpToolCall',
    'webSearch',
])
const DEFAULT_SUB_AGENT_LABEL = 'Sub agent'

export type ActionConversationRenderGroup = {
    entries: AgentConversationEventEntry[]
    key: string
    kind: 'completedToolCalls'
} | {
    entry: AgentConversationEntry
    key: string
    kind: 'entry'
} | {
    entry: AgentConversationEventEntry
    groups: ActionConversationRenderGroup[]
    key: string
    kind: 'subAgent'
    label: string
    runningCount: number
}

function isToolCall(entry: AgentConversationEventEntry) {
    return TOOL_CALL_EVENT_TYPES.has(entry.type) || entry.type.startsWith('tool.')
}

function isCompletedToolCall(entry: AgentConversationEventEntry) {
    return entry.status === 'completed' && isToolCall(entry)
}

function appendCompletedToolCallRun(
    groups: ActionConversationRenderGroup[],
    entries: AgentConversationEventEntry[],
) {
    if (entries.length === 0) return
    if (entries.length === 1) {
        const [entry] = entries
        groups.push({ entry, key: eventIdentity(entry), kind: 'entry' })
        return
    }

    groups.push({ entries, key: eventIdentity(entries[0]), kind: 'completedToolCalls' })
}

function parsedToolInput(content: string) {
    try {
        const parsed: unknown = JSON.parse(content)
        if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return null

        return parsed as Record<string, unknown>
    } catch {
        return null
    }
}

/**
 * Claude's `Agent` call and Codex's `collabAgentToolCall` both spawn sub agents whose entries name them
 * through `parentItemId`.
 */
function isSpawningCall(entry: AgentConversationEntry): entry is AgentConversationEventEntry {
    if (entry.kind !== 'event' || !entry.providerItemId) return false

    return entry.type === 'tool.Agent' || entry.type === 'collabAgentToolCall'
}

/**
 * The spawning `Agent` call names the sub agent in its input, but that input is still partial JSON
 * while the call streams, so a label already carried by the sub agent's own entries is the fallback.
 * A Codex collaboration call already carries `Collaboration: <tool>` as its label, so its content, which
 * holds the prompt rather than tool input, is never parsed.
 */
function subAgentLabel(entry: AgentConversationEventEntry, children: AgentConversationEventEntry[]) {
    if (entry.type === 'collabAgentToolCall') return entry.label ?? DEFAULT_SUB_AGENT_LABEL
    const input = parsedToolInput(entry.content)
    const subagentType = input?.subagent_type
    if (typeof subagentType === 'string' && subagentType.length > 0) return subagentType
    const description = input?.description
    if (typeof description === 'string' && description.length > 0) return description
    const labelled = children.find((child) => (
        child.type === 'agentMessage' && typeof child.label === 'string' && child.label.length > 0
    ))

    return labelled?.label ?? DEFAULT_SUB_AGENT_LABEL
}

function agentCallsByProviderId(entries: AgentConversationEntry[]) {
    return new Map(entries
        .filter(isSpawningCall)
        .map((entry) => [entry.providerItemId as string, entry]))
}

function hasOwnershipCycle(entry: AgentConversationEventEntry, agentCalls: Map<string, AgentConversationEventEntry>) {
    if (!entry.providerItemId) return false
    const visitedParentIds = new Set<string>()
    let parentItemId = entry.parentItemId
    while (parentItemId) {
        if (parentItemId === entry.providerItemId || visitedParentIds.has(parentItemId)) return true
        visitedParentIds.add(parentItemId)
        parentItemId = agentCalls.get(parentItemId)?.parentItemId
    }

    return false
}

function childEntriesByParentId(
    entries: AgentConversationEntry[],
    agentCalls: Map<string, AgentConversationEventEntry>,
) {
    const childEntries = new Map<string, AgentConversationEventEntry[]>()
    const ownedEntries = new Set<AgentConversationEventEntry>()
    for (const entry of entries) {
        if (entry.kind !== 'event' || !entry.parentItemId || !agentCalls.has(entry.parentItemId)) continue
        if (hasOwnershipCycle(entry, agentCalls)) continue
        const children = childEntries.get(entry.parentItemId) ?? []
        children.push(entry)
        childEntries.set(entry.parentItemId, children)
        ownedEntries.add(entry)
    }

    return { childEntries, ownedEntries }
}

function shouldRenderSubAgentGroup(entry: AgentConversationEventEntry, descendants: AgentConversationEventEntry[]) {
    if (descendants.length > 0) return true

    return entry.type === 'collabAgentToolCall'
        && (entry.status !== 'completed' || (entry.runningSubThreads ?? 0) > 0)
}

function buildGroups(
    entries: AgentConversationEntry[],
    agentCalls: Map<string, AgentConversationEventEntry>,
    childEntries: Map<string, AgentConversationEventEntry[]>,
) {
    const groups: ActionConversationRenderGroup[] = []
    let completedToolCalls: AgentConversationEventEntry[] = []

    for (const entry of entries) {
        const descendants = isSpawningCall(entry) ? childEntries.get(entry.providerItemId as string) ?? [] : []
        const isAgentCall = isSpawningCall(entry) && shouldRenderSubAgentGroup(entry, descendants)
        if (entry.kind === 'event' && !isAgentCall && isCompletedToolCall(entry)) {
            completedToolCalls.push(entry)
            continue
        }

        appendCompletedToolCallRun(groups, completedToolCalls)
        completedToolCalls = []
        if (isAgentCall) {
            groups.push({
                entry,
                groups: buildGroups(descendants, agentCalls, childEntries),
                key: eventIdentity(entry),
                kind: 'subAgent',
                label: subAgentLabel(entry, descendants),
                runningCount: entry.runningSubThreads ?? 0,
            })
            continue
        }
        const key = entry.kind === 'event' ? eventIdentity(entry) : entry.id
        groups.push({ entry, key, kind: 'entry' })
    }

    appendCompletedToolCallRun(groups, completedToolCalls)

    return groups
}

/** Builds UI-only groups without changing canonical conversation entries. */
export function buildActionConversationRenderGroups(entries: AgentConversationEntry[]) {
    const agentCalls = agentCallsByProviderId(entries)
    const { childEntries, ownedEntries } = childEntriesByParentId(entries, agentCalls)
    const rootEntries = entries.filter((entry) => entry.kind !== 'event' || !ownedEntries.has(entry))

    return buildGroups(rootEntries, agentCalls, childEntries)
}

import ExpandLessOutlined from '@mui/icons-material/ExpandLessOutlined'
import ExpandMoreOutlined from '@mui/icons-material/ExpandMoreOutlined'
import { Box, Button, Typography } from '@mui/material'
import { useState } from 'react'
import type { AgentConversationEventEntry } from '../../../data/data_types'
import { ActionConversationEventRow } from './action_conversation_event_row'
import { eventIdentity } from './event_display'

interface CompletedToolCallGroupProps {
    entries: AgentConversationEventEntry[]
}

/** Shows adjacent completed tool calls as one expandable summary. */
export function CompletedToolCallGroup({ entries }: CompletedToolCallGroupProps) {
    const [expanded, setExpanded] = useState(false)
    const toggleExpanded = () => {
        setExpanded((current) => !current)
    }

    return (
        <Box
            aria-label="Completed tool calls"
            role="group"
            sx={{ border: '1px solid', borderColor: 'divider', borderRadius: 1, flexShrink: 0, minWidth: 0, overflow: 'hidden' }}
        >
            <Button
                aria-expanded={expanded}
                endIcon={expanded ? <ExpandLessOutlined /> : <ExpandMoreOutlined />}
                fullWidth
                onClick={toggleExpanded}
                sx={{ color: 'text.secondary', justifyContent: 'space-between', minWidth: 0, px: 1, py: 0.75, textAlign: 'left' }}
            >
                <Typography noWrap sx={{ minWidth: 0 }} variant="caption">Tools called ({entries.length})</Typography>
            </Button>
            {expanded ? entries.map((entry) => (
                <Box
                    key={eventIdentity(entry)}
                    sx={{ borderColor: 'divider', minWidth: 0 }}
                >
                    <ActionConversationEventRow entry={entry} grouped />
                </Box>
            )) : null}
        </Box>
    )
}

import { Box } from '@mui/material'
import { memo } from 'react'
import type { AgentConversationEventEntry } from '../../../data/data_types'
import { AgentToolEvent } from './agent_tool_event'
import { CommandExecutionEvent } from './command_execution_event'
import { ReasoningEvent } from './reasoning_event'

interface ActionConversationEventRowProps {
    entry: AgentConversationEventEntry
    grouped: boolean
}

/** Renders one referentially stable transcript event. */
export const ActionConversationEventRow = memo(function ActionConversationEventRow({ entry, grouped }: ActionConversationEventRowProps) {
    if (entry.type === 'reasoning') return <Box sx={{ minWidth: 0 }}><ReasoningEvent event={entry} /></Box>
    if (entry.type === 'commandExecution') {
        return <Box sx={{ minWidth: 0 }}><CommandExecutionEvent event={entry} grouped={grouped} /></Box>
    }

    return <Box sx={{ minWidth: 0 }}><AgentToolEvent event={entry} grouped={grouped} /></Box>
})

import TerminalOutlined from '@mui/icons-material/TerminalOutlined'
import { Box, Button, Stack, Typography } from '@mui/material'
import { useState } from 'react'
import type { AgentConversationEvent } from '../../../data/data_types'
import { commandPreview, eventHasError, eventStatusLabel } from './event_display'

const COMMAND_DETAIL_MAX_HEIGHT = 320

interface CommandExecutionEventProps {
    event: AgentConversationEvent
    grouped: boolean
}

function detailValue(value: string | number) {
    return (
        <Box
            component="pre"
            sx={{
                fontFamily: 'monospace',
                m: 0,
                overflowWrap: 'anywhere',
                whiteSpace: 'pre-wrap',
                wordBreak: 'break-word',
            }}
        >
            {value}
        </Box>
    )
}

/** Collapsed command lifecycle entry with exact execution detail on demand. */
export function CommandExecutionEvent({ event, grouped }: CommandExecutionEventProps) {
    const [expanded, setExpanded] = useState(false)
    const preview = commandPreview(event.command) || 'Command'
    const hasError = eventHasError(event.status)
    const durationMs = typeof event.durationMs === 'number' && Number.isFinite(event.durationMs)
        ? event.durationMs
        : null
    const exitCode = typeof event.exitCode === 'number' && Number.isSafeInteger(event.exitCode)
        ? event.exitCode
        : null
    const toggleExpanded = () => {
        setExpanded((current) => !current)
    }

    return (
        <Box
            sx={{
                border: grouped ? 'none' : '1px solid',
                borderColor: hasError ? 'error.main' : 'divider',
                borderRadius: grouped ? 0 : 1,
                flexShrink: 0,
                minWidth: 0,
                overflow: 'hidden',
            }}
        >
            <Button
                aria-expanded={expanded}
                aria-label={`Command details: ${preview}`}
                fullWidth
                onClick={toggleExpanded}
                startIcon={<TerminalOutlined />}
                sx={{
                    color: hasError ? 'error.main' : 'text.secondary',
                    display: 'flex',
                    justifyContent: 'flex-start',
                    minWidth: 0,
                    px: 1,
                    py: 0.75,
                    textAlign: 'left',
                }}
            >
                <Stack direction="row" spacing={1} sx={{ alignItems: 'center', minWidth: 0, width: '100%' }}>
                    <Typography noWrap sx={{ flex: 1, minWidth: 0 }} variant="caption">{preview}</Typography>
                    <Typography color="inherit" role="status" variant="caption">
                        {eventStatusLabel(event.status)}
                    </Typography>
                </Stack>
            </Button>
            {expanded ? (
                <Stack
                    spacing={1}
                    sx={{
                        bgcolor: 'background.default',
                        borderTop: '1px solid',
                        borderColor: 'divider',
                        color: hasError ? 'error.main' : 'text.secondary',
                        maxHeight: COMMAND_DETAIL_MAX_HEIGHT,
                        minWidth: 0,
                        overflow: 'auto',
                        p: 1,
                    }}
                >
                    <Box><Typography color="custom.text3" variant="caption">Command</Typography>{detailValue(event.command ?? '')}</Box>
                    {event.workingDirectory ? (
                        <Box><Typography color="custom.text3" variant="caption">Working directory</Typography>{detailValue(event.workingDirectory)}</Box>
                    ) : null}
                    {event.content ? (
                        <Box><Typography color="custom.text3" variant="caption">Output</Typography>{detailValue(event.content)}</Box>
                    ) : null}
                    {exitCode !== null || durationMs !== null ? (
                        <Stack direction="row" spacing={2}>
                            {exitCode !== null ? (
                                <Typography variant="caption">Exit code: {exitCode}</Typography>
                            ) : null}
                            {durationMs !== null ? (
                                <Typography variant="caption">Duration: {durationMs} ms</Typography>
                            ) : null}
                        </Stack>
                    ) : null}
                </Stack>
            ) : null}
        </Box>
    )
}

import BuildOutlined from '@mui/icons-material/BuildOutlined'
import { Box, Button, Stack, Typography } from '@mui/material'
import { useState } from 'react'
import type { AgentConversationEvent } from '../../../data/data_types'
import { eventHasError, eventStatusLabel, readableEventText } from './event_display'

const TOOL_DETAIL_MAX_HEIGHT = 240

interface AgentToolEventProps {
    event: AgentConversationEvent
    grouped: boolean
}

/** Generic compact renderer for normalized Codex tool and system events. */
export function AgentToolEvent({ event, grouped }: AgentToolEventProps) {
    const [expanded, setExpanded] = useState(false)
    const label = event.label ?? 'Agent event'
    const hasError = eventHasError(event.status)
    const contentLines = readableEventText(event.content)
    const outputLines = readableEventText(event.output)
    const durationMs = typeof event.durationMs === 'number' && Number.isFinite(event.durationMs)
        ? event.durationMs
        : null
    const hasDetail = contentLines.length > 0 || outputLines.length > 0 || durationMs !== null
    const toggleExpanded = () => {
        setExpanded((current) => !current)
    }

    return (
        <Box
            sx={{
                border: grouped ? 'none' : '1px solid',
                borderColor: hasError ? 'error.main' : 'divider',
                borderRadius: grouped ? 0 : 1,
                flexShrink: 0,
                minWidth: 0,
                overflow: 'hidden',
            }}
        >
            <Button
                aria-expanded={hasDetail ? expanded : undefined}
                aria-label={`${label} details`}
                disabled={!hasDetail}
                fullWidth
                onClick={toggleExpanded}
                startIcon={<BuildOutlined />}
                sx={{
                    color: hasError ? 'error.main' : 'text.secondary',
                    display: 'flex',
                    justifyContent: 'flex-start',
                    minWidth: 0,
                    px: 1,
                    py: 0.75,
                    textAlign: 'left',
                }}
            >
                <Stack direction="row" spacing={1} sx={{ alignItems: 'center', minWidth: 0, width: '100%' }}>
                    <Typography noWrap sx={{ flex: 1, minWidth: 0 }} variant="caption">{label}</Typography>
                    <Typography color="inherit" role="status" variant="caption">
                        {eventStatusLabel(event.status)}
                    </Typography>
                </Stack>
            </Button>
            {expanded ? (
                <Stack
                    spacing={1}
                    sx={{
                        bgcolor: 'background.default',
                        borderTop: '1px solid',
                        borderColor: 'divider',
                        color: hasError ? 'error.main' : 'text.secondary',
                        maxHeight: TOOL_DETAIL_MAX_HEIGHT,
                        minWidth: 0,
                        overflow: 'auto',
                        p: 1,
                    }}
                >
                    {contentLines.map((line, index) => (
                        <Typography key={`content-${index}`} sx={{ overflowWrap: 'anywhere', whiteSpace: 'pre-wrap' }} variant="body2">
                            {line}
                        </Typography>
                    ))}
                    {outputLines.map((line, index) => (
                        <Typography key={`output-${index}`} sx={{ overflowWrap: 'anywhere', whiteSpace: 'pre-wrap' }} variant="body2">
                            {line}
                        </Typography>
                    ))}
                    {durationMs !== null ? (
                        <Typography variant="caption">Duration: {durationMs} ms</Typography>
                    ) : null}
                </Stack>
            ) : null}
        </Box>
    )
}

